class EventEmitter {
  #listeners = {};

  on(event, fn) {
    (this.#listeners[event] ??= []).push(fn);
    return this;
  }

  emit(event, ...args) {
    this.#listeners[event]?.forEach(fn => fn(...args));
    return this;
  }

  off(event, fn) {
    this.#listeners[event] = this.#listeners[event]?.filter(f => f !== fn);
    return this;
  }
}

