class CommandManager {
  #history = [];
  #future  = [];

  execute(cmd) {
    cmd.execute();
    this.#history.push(cmd);
    this.#future = [];
  }

  undo() {
    const cmd = this.#history.pop();
    if (cmd) { cmd.undo(); this.#future.push(cmd); }
