function useState(initial) {
  const i = index++;
  if (state[i] === undefined) state[i] = initial;

  const setState = (newVal) => {
    state[i] = typeof newVal === 'function'
      ? newVal(state[i])
      : newVal;
    rerender();
  };

  return [state[i], setState];
}

function rerender() {
  index = 0;
  render();
}

let activeEffect = null;

function reactive(obj) {
  const deps = new Map();
  return new Proxy(obj, {
    get(target, key) {
      if (activeEffect) {
        (deps.get(key) ?? deps.set(key, new Set()).get(key)).add(activeEffect);
      }
      return target[key];
    },
    set(target, key, val) {
      target[key] = val;
      deps.get(key)?.forEach(fn => fn());
      return true;
    },
  });
}

function effect(fn) {
  activeEffect = fn;
  fn();
  activeEffect = null;
}

const createApp = (root) => {
  const state   = reactive({ count: 0, user: null });
  const plugins = [];

  const app = {
    use(plugin)  { plugins.push(plugin); return app; },
    mount() {
      plugins.forEach(p => p.install(app, state));
      effect(() => render(root, view(state)));
    },
  };

  return app;
};

const logPlugin = { install: (app, state) => effect(() => console.log('State:', { ...state })) };

createApp('#app')
